74	/** One of the sheet's rates for a grade: a percent with two decimals, in force from its from-date
75	 *  (or from the beginning of time, when it has none) until the grade's next rate. */
76	@Entity
77	@Table(name = "rate")
78	public class Rate {
79	
80	    @Id
81	    @GeneratedValue(strategy = GenerationType.IDENTITY)
82	    private Long id;
83	
84	    @Column(name = "sheet_id", nullable = false)
85	    private String sheetId;
86	
87	    @Enumerated(EnumType.STRING)
88	    @Column(name = "grade", nullable = false)
89	    private Grade grade;
90	
91	    @Column(name = "from_date")
92	    private LocalDate from;
93	
94	    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
95	    private BigDecimal pct;
96	
97	    protected Rate() {
98	    }
99	
100	    public Rate(String sheetId, Grade grade, LocalDate from, BigDecimal pct) {
101	        this.sheetId = sheetId;
102	        this.grade = grade;
103	        this.from = from;
104	        setPct(pct);
105	    }
106	
107	    public Long getId() {
108	        return id;
109	    }
110	
111	    public String getSheetId() {
112	        return sheetId;
113	    }
114	
115	    public Grade getGrade() {
116	        return grade;
117	    }
118	
119	    /** The date the rate is in force from, or null when it applies from the beginning of time. */
120	    public LocalDate getFrom() {
121	        return from;
122	    }
123	
124	    public BigDecimal getPct() {
125	        return pct;
126	    }
127	
128	    /** Change the percent; it is kept to two decimals. */
129	    public void setPct(BigDecimal pct) {
130	        this.pct = pct.setScale(2);
131	    }
132	
133	    /** Whether the rate is in force on or before this date. */
134	    public boolean appliesBy(LocalDate date) {
135	        return from == null || !from.isAfter(date);
136	    }
137	}
