174	import net.officefloor.hq.app.rollup.Rollup;
175	import net.officefloor.hq.app.sheet.SheetService;
176	import org.springframework.dao.DataIntegrityViolationException;
177	import org.springframework.http.HttpStatus;
178	import org.springframework.stereotype.Service;
179	import org.springframework.transaction.annotation.Transactional;
180	import org.springframework.web.server.ResponseStatusException;
181	
182	@Service
183	public class RateService {
184	
185	    private final RateRepository rates;
186	    private final SheetService sheets;
187	    private final Rollup rollup;
188	    private final Audit audit;
189	
190	    public RateService(RateRepository rates, SheetService sheets, Rollup rollup, Audit audit) {
191	        this.rates = rates;
192	        this.sheets = sheets;
193	        this.rollup = rollup;
194	        this.audit = audit;
195	    }
196	
197	    /** The sheet's rates in grade order, then by from-date; a grade with no rate is left out. */
198	    @Transactional(readOnly = true)
199	    public List<Rate> list(String sheetId) {
200	        return rates.findBySheetIdInOrder(sheetId);
201	    }
202	
203	    /** The grade's rate in force on a date: the one with the latest from-date on or before it, or
204	     *  null when the date is before every rate the grade has. */
205	    @Transactional(readOnly = true)
206	    public Rate inForce(String sheetId, Grade grade, LocalDate date) {
207	        Rate inForce = null;
208	        for (Rate rate : rates.findForGrade(sheetId, grade)) {
209	            if (rate.appliesBy(date)) inForce = rate;
210	        }
211	        return inForce;
212	    }
213	
214	    /** Set the sheet's rate for a grade from a from-date (none: from the beginning of time),
215	     *  replacing the rate it had for that from-date. */
216	    @Transactional
217	    public Rate set(String sheetId, String user, Grade grade, LocalDate from, BigDecimal pct) {
218	        sheets.load(sheetId);
219	        Rollup.Snapshot before = rollup.snapshot(sheetId);
220	        Rate rate = (from == null ? rates.findFromStart(sheetId, grade) : rates.findFrom(sheetId, grade, from))
221	                .orElse(null);
222	        if (rate == null) {
223	            rate = new Rate(sheetId, grade, from, pct);
224	        } else {
225	            rate.setPct(pct);
226	        }
227	        Rate saved;
228	        try {
229	            saved = rates.saveAndFlush(rate);
230	        } catch (DataIntegrityViolationException raced) {
231	            // Another user set the same grade's rate for that from-date at the same moment.
232	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The rate was changed by someone else.");
233	        }
234	        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + saved.getGrade()
235	                + " rate=" + saved.getPct().toPlainString() + (from == null ? "" : " from=" + from));
236	        rollup.recordChanges(user, before);
237	        return saved;
238	    }
239	}
