268	 * The sheet's figures as the screen shows them: each person's claimed and due-total (late charges
269	 * included), and the sheet's
270	 * claimed-total and due-total. A change takes a snapshot before it alters anything, then
271	 * {@link #recordChanges} audits, after the change's own lines, each person whose figures moved (in the
272	 * order they were added) and then the sheet's totals when they moved.
273	 */
274	@Service
275	public class Rollup {
276	
277	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
278	
279	    /** A person's figures; a null due-total is n/a. */
280	    record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {
281	        boolean sameAs(Figures other) {
282	            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal);
283	        }
284	    }
285	
286	    /** The sheet's figures at one moment: each person's, by id in the order they were added, and the totals. */
287	    public record Snapshot(String sheetId, Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {
288	    }
289	
290	    private final PersonRepository people;
291	    private final ClaimRepository claims;
292	    private final RateRepository rates;
293	    private final SheetRepository sheets;
294	    private final SheetSettingRepository settings;
295	    private final Audit audit;
296	
297	    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
298	            SheetSettingRepository settings, Audit audit) {
299	        this.people = people;
300	        this.claims = claims;
301	        this.rates = rates;
302	        this.sheets = sheets;
303	        this.settings = settings;
304	        this.audit = audit;
305	    }
306	
307	    /** The sheet's figures as the store holds them now, within the caller's transaction. */
308	    public Snapshot snapshot(String sheetId) {
309	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
310	        BigDecimal floor = SettingService.floorOf(settings, sheetId);
311	        BigDecimal latePct = SettingService.latePctOf(settings, sheetId);
312	        LocalDate policyDate = Rounding.policyDate(SettingService.policyDateOf(settings, sheetId), today);
313	        Map<Grade, List<Rate>> ratesByGrade = new LinkedHashMap<>();
314	        for (Rate rate : rates.findBySheetIdInOrder(sheetId)) {
315	            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
316	        }
317	        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
318	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
319	            claimsByPerson.computeIfAbsent(claim.getPersonId(), p -> new ArrayList<>()).add(claim);
320	        }
321	        Map<Long, Figures> figures = new LinkedHashMap<>();
322	        BigDecimal claimedTotal = ZERO;
323	        BigDecimal dueTotal = ZERO;
324	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
325	            Grade gradeToday = today == null ? null : person.gradeOn(today);
326	            BigDecimal claimed = ZERO;
327	            BigDecimal due = ZERO;
328	            boolean keptFigure = false;
329	            List<Claim> theirs = claimsByPerson.getOrDefault(person.getId(), List.of());
330	            for (Claim claim : theirs) {
331	                if (!counts(person, claim)) continue;
332	                claimed = claimed.add(claim.getAmount());
333	                // A claim's live figure is at the grade in force on its date.
