401	    private static Rate inForce(List<Rate> gradeRates, LocalDate date) {
402	        Rate inForce = null;
403	        for (Rate rate : gradeRates) {
404	            if (rate.appliesBy(date)) inForce = rate;
405	        }
406	        return inForce;
